s.hyperlink_task_id = #{criteria.taskId}

  AND s.updated_at <= #{criteria.snapshotAt}




      AND (
        s.account_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM hyperlink_task_account_usage country_usage
          WHERE country_usage.hyperlink_task_id = s.hyperlink_task_id
            AND country_usage.account_id = s.account_id
            AND country_usage.sender_country_iso2_snapshot IS NULL
        )
      )


      AND EXISTS (
        SELECT 1
        FROM hyperlink_task_account_usage country_usage
        WHERE country_usage.hyperlink_task_id = s.hyperlink_task_id
          AND country_usage.account_id = s.account_id
          AND country_usage.sender_country_iso2_snapshot = #{criteria.senderCountryIso2}
      )




  AND COALESCE((s.success_num * 100.0) / NULLIF(s.send_total, 0), 0)
      >= #{criteria.successRateMin}


  AND COALESCE((s.success_num * 100.0) / NULLIF(s.send_total, 0), 0)
      <= #{criteria.successRateMax}
